-- A narrow staff-only directory; Auth credentials and metadata are never returned.
create or replace function public.staff_customer_directory(search text default '',page_number int default 0,page_size int default 20) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare customers jsonb;matches bigint;
begin
 perform private.require_staff();
 if search is null or length(search)>200 or page_number is null or page_number not between 0 and 100000
 or page_size is null or page_size not between 1 and 100 then raise exception 'Invalid customer search or page';end if;
 select count(*) into matches from public.profiles p join auth.users u on u.id=p.id where p.role='customer'
 and strpos(lower(p.full_name||' '||coalesce(u.email,'')),lower(btrim(search)))>0;
 select coalesce(jsonb_agg(x order by x.full_name,x.id),'[]'::jsonb) into customers from (
  select p.id,p.full_name,coalesce(u.email,'') as email,p.account_status,p.account_discount_bps,p.account_discount_changed_at
  from public.profiles p join auth.users u on u.id=p.id where p.role='customer'
  and strpos(lower(p.full_name||' '||coalesce(u.email,'')),lower(btrim(search)))>0
  order by p.full_name,p.id limit page_size offset page_number*page_size
 )x;
 return jsonb_build_object('customers',customers,'total',matches,'min_bps',0,'max_bps',10000,'business_cap_configured',false);
end $$;
create or replace function public.manage_customer_account_discount(customer_id uuid,percentage_bps int) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p public.profiles;
begin
 perform private.require_staff();select * into strict p from public.profiles where id=customer_id for update;
 perform public.set_customer_account_discount(customer_id,percentage_bps,
 case when percentage_bps=0 then 'Manager removed the account discount' else 'Manager assigned or updated the account discount' end);
 return jsonb_build_object('customer_name',p.full_name,'previous_bps',p.account_discount_bps,'percentage_bps',percentage_bps);
end $$;

-- The largest single-day commitment, not the sum across unrelated event days.
create or replace function private.equipment_committed(eid uuid) returns int
language sql stable security definer set search_path='' as $$
 select coalesce(max(x.quantity),0)::int from (
 select sum(a.quantity) as quantity from public.equipment_allocations a join public.reservations r on r.id=a.reservation_id
 where a.equipment_id=eid and r.holds_capacity and a.event_date>=(now() at time zone 'Asia/Manila')::date group by a.event_date
 )x
$$;
create or replace function public.configure_equipment(eid uuid,quantity int,is_active boolean default true) returns void
language plpgsql security definer set search_path='' as $$
declare item public.equipment_inventory;committed int;
begin
 perform private.require_staff();
 if quantity is null or quantity not between 0 and 1000000 or is_active is null then raise exception 'Enter confirmed usable stock as a whole number from 0 to 1000000';end if;
 select * into strict item from public.equipment_inventory where id=eid for update;
 committed=private.equipment_committed(eid);
 if quantity<committed and (item.usable_quantity is null or quantity<item.usable_quantity) then raise exception 'Cannot reduce % below % chairs committed on an upcoming event date. Resolve the booking allocation first',item.name,committed;end if;
 update public.equipment_inventory set usable_quantity=quantity,active=is_active,updated_at=now() where id=eid;
 perform private.audit('equipment.stock_changed',eid::text,jsonb_build_object('previous_quantity',item.usable_quantity,'quantity',quantity,'change',quantity-item.usable_quantity,'active',is_active,'committed',committed));
end $$;
create or replace function public.adjust_equipment_stock(eid uuid,adjustment text,quantity int,note text default '',operation_id uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item public.equipment_inventory;next_quantity int;committed int;previous jsonb;result jsonb;
begin
 perform private.require_staff();
 if adjustment is null or adjustment not in ('add','remove') or quantity is null or quantity not between 1 and 1000000
 or note is null or length(note)>500 or operation_id is null then raise exception 'Choose Add or Remove and a positive whole quantity within the supported range';end if;
 select * into strict item from public.equipment_inventory where id=eid for update;
 select details into previous from public.audit_logs where action='equipment.stock_adjusted' and entity_id=eid::text
 and actor_id=auth.uid() and details->>'operation_id'=operation_id::text limit 1;
 if found then
  if previous->>'adjustment'<>adjustment or (previous->>'quantity')::int<>quantity or previous->>'note'<>btrim(note) then raise exception 'This stock request was already used with different details';end if;
  return previous;
 end if;
 if item.usable_quantity is null then raise exception 'Confirm the actual starting stock before adding or removing chairs';end if;
 next_quantity=item.usable_quantity+case when adjustment='add' then quantity else -quantity end;
 if next_quantity not between 0 and 1000000 then raise exception 'The resulting stock must be between 0 and 1000000 chairs';end if;
 committed=private.equipment_committed(eid);
 if adjustment='remove' and next_quantity<committed then raise exception 'Cannot remove these chairs: % are committed on an upcoming event date. At most % can be removed',committed,greatest(item.usable_quantity-committed,0);end if;
 update public.equipment_inventory set usable_quantity=next_quantity,updated_at=now() where id=eid;
 result=jsonb_build_object('operation_id',operation_id,'equipment_name',item.name,'adjustment',adjustment,'quantity',quantity,'previous_quantity',item.usable_quantity,'total',next_quantity,'change',next_quantity-item.usable_quantity,'committed',committed,'note',btrim(note));
 perform private.audit('equipment.stock_adjusted',eid::text,result);return result;
end $$;

create or replace function public.set_equipment_active(eid uuid,is_active boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item public.equipment_inventory;
begin
 perform private.require_staff();if is_active is null then raise exception 'Choose availability';end if;
 select * into strict item from public.equipment_inventory where id=eid for update;
 update public.equipment_inventory set active=is_active,updated_at=now() where id=eid;
 perform private.audit('equipment.availability_changed',eid::text,jsonb_build_object('previous_active',item.active,'active',is_active,'quantity',item.usable_quantity));
 return jsonb_build_object('equipment_name',item.name,'adjustment',case when is_active then 'resumed' else 'paused' end,'quantity',0,'total',item.usable_quantity);
end $$;
create or replace function public.confirm_equipment_stock(eid uuid,quantity int) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item public.equipment_inventory;
begin
 perform private.require_staff();select * into strict item from public.equipment_inventory where id=eid for update;
 if item.usable_quantity is not null then raise exception 'Starting stock was already confirmed. Reload and use Add Stock or Remove Stock';end if;
 perform public.configure_equipment(eid,quantity,item.active);
 return jsonb_build_object('equipment_name',item.name,'adjustment','initial','quantity',quantity,'total',quantity);
end $$;

-- Retain shared whole-day allocation, confirmed/pending-cancellation holds and
-- existing deterministic row locking. Total selected seating cannot exceed guests.
create or replace function private.sync_equipment(rid uuid,check_request boolean default false) returns void
language plpgsql security definer set search_path='' as $$
declare r public.reservations;i public.equipment_inventory;requested int;allocated int;old_allocation public.equipment_allocations;
begin
 select * into r from public.reservations where id=rid for update;if not found then return;end if;
 if check_request and exists(select 1 from public.menu_sets where id=r.menu_set_id and pricing_version=2)
 and (select coalesce(sum(chair_quantity),0) from public.reservation_tables_chairs where reservation_id=rid)>r.guests then raise exception 'Selected guest chairs exceed the guest count';end if;
 for i in select * from public.equipment_inventory order by id for update loop
  select coalesce(sum(s.chair_quantity),0)::int into requested from public.reservation_tables_chairs s join public.chair_types c on c.id=s.chair_type_id where s.reservation_id=rid and c.equipment_id=i.id;
  select * into old_allocation from public.equipment_allocations where reservation_id=rid and equipment_id=i.id;
  if requested>r.guests and (r.holds_capacity or check_request) then raise exception 'Requested % quantity exceeds the guest count',i.name;end if;
  if (r.holds_capacity or check_request) and requested>0 and not coalesce((not check_request and old_allocation.event_date=r.event_date and requested<=old_allocation.quantity),false) then
   if i.usable_quantity is null then raise exception 'Confirmed % stock is not configured. Ask the manager to set usable inventory',i.name;end if;
   if not i.active then raise exception '% is unavailable for new allocations',i.name;end if;
   select coalesce(sum(quantity),0)::int into allocated from public.equipment_allocations where equipment_id=i.id and event_date=r.event_date and reservation_id<>rid;
   if requested>greatest(i.usable_quantity-allocated,0) then raise exception '% shortage: % requested, % available for %. Reduce chairs or choose another date',i.name,requested,greatest(i.usable_quantity-allocated,0),r.event_date;end if;
  end if;
  if r.holds_capacity and requested>0 then
   insert into public.equipment_allocations values(rid,i.id,r.event_date,requested,now()) on conflict(reservation_id,equipment_id) do update set event_date=excluded.event_date,quantity=excluded.quantity,updated_at=excluded.updated_at;
   if old_allocation.quantity is distinct from requested or old_allocation.event_date is distinct from r.event_date then perform private.audit('equipment.allocated',rid::text,jsonb_build_object('equipment',i.code,'date',r.event_date,'quantity',requested));end if;
  else
   delete from public.equipment_allocations where reservation_id=rid and equipment_id=i.id;
   if found then perform private.audit('equipment.released',rid::text,jsonb_build_object('equipment',i.code));end if;
  end if;
 end loop;
end $$;

